import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { FaUserMd, FaStethoscope, FaCalendarCheck } from 'react-icons/fa';
import StatsCard from '../../components/Common/StatsCard';

const DoctorDashboard = () => {
  const [stats, setStats] = useState({
    assignedPatients: 0,
    totalTreatments: 0,
    todayTreatments: 0,
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Simulate API call
    setTimeout(() => {
      setStats({
        assignedPatients: 12,
        totalTreatments: 45,
        todayTreatments: 3,
      });
      setLoading(false);
    }, 1000);
  }, []);

  const statCards = [
    { title: 'Assigned Patients', value: stats.assignedPatients, icon: FaUserMd, color: 'blue' },
    { title: 'Total Treatments', value: stats.totalTreatments, icon: FaStethoscope, color: 'green' },
    { title: "Today's Treatments", value: stats.todayTreatments, icon: FaCalendarCheck, color: 'purple' },
  ];

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="w-16 h-16 border-4 border-primary-600 border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-gray-900">Doctor Dashboard</h1>
        <p className="text-gray-500">Welcome back, Doctor! Here's your patient overview.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {statCards.map((stat) => (
          <StatsCard key={stat.title} {...stat} />
        ))}
      </div>

      <div className="card p-6">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">Recent Patients</h2>
        <div className="space-y-3">
          <div className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
            <div>
              <p className="font-medium text-gray-800">Ahmed Hassan</p>
              <p className="text-sm text-gray-500">Diagnosis: Malaria</p>
            </div>
            <span className="badge badge-info">In Treatment</span>
          </div>
          <div className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
            <div>
              <p className="font-medium text-gray-800">Mary Wanjiru</p>
              <p className="text-sm text-gray-500">Diagnosis: Hypertension</p>
            </div>
            <span className="badge badge-success">Discharged</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DoctorDashboard;
